function solve(c) {
  // Catat n terakhir yang masih GAGAL, yaitu c·n² belum dikalahkan 2^n.
  let terakhirGagal = 0
  for (let n = 1; n <= 100; n++) {
    if (c * n * n >= 2 ** n) terakhirGagal = n
  }
  // Setelah n itu, 2^n selalu menang.
  return terakhirGagal + 1
}
